import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(n + 1)]
    degree = [0] * (n + 1)

    for _ in range(n):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)
        degree[u] += 1
        degree[v] += 1

    dist = [-1] * (n + 1)
    queue = deque()

    for i in range(1, n + 1):
        if degree[i] < 2:
            queue.append(i)
            dist[i] = 0

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                degree[v] -= 1
                if degree[v] == 1:
                    dist[v] = dist[u] + 1
                    queue.append(v)

    for i in range(1, n + 1): 
        if dist[i] == -1:
            dist[i] = 0

    result = []
    for i in range(1, n + 1):
        result.append(str(dist[i]))

    print(" ".join(result))

if __name__ == "__main__":
    solve()
